def fatorial(n: int) -> int:
    """Calcula o fatorial de n usando recursão."""
    if n in (0, 1):
        return 1
    return n * fatorial(n - 1)


def soma_digitos(n: int) -> int:
    """Soma os dígitos de n recursivamente."""
    if n == 0:
        return 0
    return n % 10 + soma_digitos(n // 10)

